"use client";

import { useState } from "react";

type Unit = "c" | "f" | "k";

type Values = Record<Unit, string>;

const ABSOLUTE_ZERO = { c: -273.15, f: -459.67, k: 0 };

const formatNumber = (value: number) => {
  if (!Number.isFinite(value)) return "";
  return String(Number(value.toFixed(4)));
};

const parseValue = (value: string) => {
  if (value.trim() === "") return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
};

export default function TemperatureConverterPage() {
  const [values, setValues] = useState<Values>({ c: "", f: "", k: "" });

  const handleChange = (unit: Unit, raw: string) => {
    setValues((prev) => {
      if (raw.trim() === "" || raw === "-" || raw === "." || raw === "-.") {
        return { ...prev, [unit]: raw };
      }
      const numeric = Number(raw);
      if (!Number.isFinite(numeric)) {
        return { ...prev, [unit]: raw };
      }

      const celsius =
        unit === "c" ? numeric : unit === "f" ? (numeric - 32) * (5 / 9) : numeric - 273.15;
      const fahrenheit = celsius * (9 / 5) + 32;
      const kelvin = celsius + 273.15;

      return {
        c: unit === "c" ? raw : formatNumber(celsius),
        f: unit === "f" ? raw : formatNumber(fahrenheit),
        k: unit === "k" ? raw : formatNumber(kelvin),
      };
    });
  };

  const c = parseValue(values.c);
  const f = parseValue(values.f);
  const k = parseValue(values.k);

  const belowAbsoluteZero =
    (c !== null && c < ABSOLUTE_ZERO.c) ||
    (f !== null && f < ABSOLUTE_ZERO.f) ||
    (k !== null && k < ABSOLUTE_ZERO.k);

  return (
    <main style={{ maxWidth: 560, margin: "4rem auto", padding: "0 1rem", fontFamily: "system-ui, sans-serif" }}>
      <h1 style={{ fontSize: "2rem", marginBottom: "0.5rem" }}>Temperature Converter</h1>
      <p style={{ color: "#555", marginTop: 0, marginBottom: "2rem" }}>
        Type in any field to convert between Celsius, Fahrenheit, and Kelvin.
      </p>

      <div style={{ display: "grid", gap: "1rem" }}>
        <label style={labelStyle}>
          <span>Celsius (°C)</span>
          <input
            inputMode="decimal"
            value={values.c}
            onChange={(e) => handleChange("c", e.target.value)}
            style={inputStyle}
            placeholder="e.g. 21"
          />
        </label>

        <label style={labelStyle}>
          <span>Fahrenheit (°F)</span>
          <input
            inputMode="decimal"
            value={values.f}
            onChange={(e) => handleChange("f", e.target.value)}
            style={inputStyle}
            placeholder="e.g. 69.8"
          />
        </label>

        <label style={labelStyle}>
          <span>Kelvin (K)</span>
          <input
            inputMode="decimal"
            value={values.k}
            onChange={(e) => handleChange("k", e.target.value)}
            style={inputStyle}
            placeholder="e.g. 294.15"
          />
        </label>
      </div>

      {belowAbsoluteZero && (
        <p role="alert" style={warningStyle}>
          Warning: that temperature is below absolute zero. The lowest possible values are
          -273.15 °C, -459.67 °F, or 0 K.
        </p>
      )}
    </main>
  );
}

const labelStyle = {
  display: "grid",
  gap: "0.35rem",
  fontWeight: 600,
} satisfies React.CSSProperties;

const inputStyle = {
  width: "100%",
  boxSizing: "border-box",
  padding: "0.7rem 0.8rem",
  fontSize: "1rem",
  border: "1px solid #bbb",
  borderRadius: "8px",
} satisfies React.CSSProperties;

