```tsx
"use client";

import { useState } from "react";

type Scale = "celsius" | "fahrenheit" | "kelvin";

const toCelsius: Record<Scale, (v: number) => number> = {
  celsius: (v) => v,
  fahrenheit: (v) => ((v - 32) * 5) / 9,
  kelvin: (v) => v - 273.15,
};

const fromCelsius: Record<Scale, (c: number) => number> = {
  celsius: (c) => c,
  fahrenheit: (c) => (c * 9) / 5 + 32,
  kelvin: (c) => c + 273.15,
};

const LABELS: Record<Scale, string> = { celsius: "Celsius (°C)", fahrenheit: "Fahrenheit (°F)", kelvin: "Kelvin (K)" };

export default function TemperaturePage() {
  const [source, setSource] = useState<{ scale: Scale; raw: string }>({ scale: "celsius", raw: "20" });

  const parsed = Number.parseFloat(source.raw);
  const celsius = Number.isFinite(parsed) ? toCelsius[source.scale](parsed) : null;

  const shown = (scale: Scale) => {
    if (scale === source.scale) return source.raw;
    if (celsius === null) return "";
    return String(Math.round(fromCelsius[scale](celsius) * 100) / 100);
  };

  return (
    <main style={{ maxWidth: 360, margin: "3rem auto", fontFamily: "system-ui, sans-serif" }}>
      <h1>Temperature converter</h1>
      {(Object.keys(LABELS) as Scale[]).map((scale) => (
        <label key={scale} style={{ display: "block", marginTop: 12 }}>
          {LABELS[scale]}
          <input
            inputMode="decimal"
            value={shown(scale)}
            onChange={(event) => setSource({ scale, raw: event.target.value })}
            style={{ display: "block", width: "100%", padding: 8, marginTop: 4 }}
          />
        </label>
      ))}
      {celsius !== null && celsius < -273.15 && <p role="alert">That is below absolute zero.</p>}
    </main>
  );
}
```

