```tsx
import { useCallback, useEffect, useRef, useState } from "react";

type Swatch = { name: string; hex: string };

const SWATCHES: readonly Swatch[] = [
  { name: "Slate", hex: "#64748B" },
  { name: "Red", hex: "#EF4444" },
  { name: "Orange", hex: "#F97316" },
  { name: "Amber", hex: "#F59E0B" },
  { name: "Lime", hex: "#84CC16" },
  { name: "Green", hex: "#22C55E" },
  { name: "Emerald", hex: "#10B981" },
  { name: "Teal", hex: "#14B8A6" },
  { name: "Cyan", hex: "#06B6D4" },
  { name: "Sky", hex: "#0EA5E9" },
  { name: "Blue", hex: "#3B82F6" },
  { name: "Indigo", hex: "#6366F1" },
  { name: "Violet", hex: "#8B5CF6" },
  { name: "Purple", hex: "#A855F7" },
  { name: "Pink", hex: "#EC4899" },
  { name: "Rose", hex: "#F43F5E" },
];

const FEEDBACK_MS = 1600;

/** Rough perceptual check so overlay icons stay legible on light swatches. */
function isLightHex(hex: string): boolean {
  const value = Number.parseInt(hex.slice(1), 16);
  const r = (value >> 16) & 255;
  const g = (value >> 8) & 255;
  const b = value & 255;
  return (0.299 * r + 0.587 * g + 0.114 * b) / 255 > 0.6;
}

async function copyText(text: string): Promise<void> {
  if (navigator.clipboard && window.isSecureContext) {
    await navigator.clipboard.writeText(text);
    return;
  }
  // Fallback for non-secure contexts / older browsers.
  const el = document.createElement("textarea");
  el.value = text;
  el.setAttribute("readonly", "");
  el.style.position = "fixed";
  el.style.opacity = "0";
  document.body.appendChild(el);
  el.select();
  const ok = document.execCommand("copy");
  document.body.removeChild(el);
  if (!ok) throw new Error("Copy command was rejected");
}

function CheckIcon({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={3}
      strokeLinecap="round"
      strokeLinejoin="round"
      className={className}
      aria-hidden="true"
    >
      <path d="M20 6 9 17l-5-5" />
    </svg>
  );
}

function CopyIcon({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      className={className}
      aria-hidden="true"
    >
      <rect x="9" y="9" width="13" height="13" rx="2" />
      <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
    </svg>
  );
}

export default function ColorSwatchGrid() {
  const [copied, setCopied] = useState<Swatch | null>(null);
  const [failed, setFailed] = useState(false);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    return () => {
      if (timerRef.current !== null) window.clearTimeout(timerRef.current);
    };
  }, []);

  const handleCopy = useCallback(async (swatch: Swatch) => {
    try {
      await copyText(swatch.hex);
      setFailed(false);
      setCopied(swatch);
    } catch {
      setFailed(true);
      setCopied(null);
    }

    if (timerRef.current !== null) window.clearTimeout(timerRef.current);
    timerRef.current = window.setTimeout(() => {
      setCopied(null);
      setFailed(false);
    }, FEEDBACK_MS);
  }, []);

  return (
    <div className="mx-auto w-full max-w-sm rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
      <div className="mb-4 flex items-baseline justify-between">
        <h2 className="text-base font-semibold text-slate-900">Palette</h2>
        <span className="text-xs text-slate-400">16 colors</span>
      </div>

      <div className="grid grid-cols-4 gap-2.5" role="group" aria-label="Color swatches">
        {SWATCHES.map((swatch) => {
          const isCopied = copied?.hex === swatch.hex;
          const light = isLightHex(swatch.hex);
          const iconTone = light ? "text-slate-900" : "text-white";

          return (
            <button
              key={swatch.hex}
              type="button"
              onClick={() => void handleCopy(swatch)}
              title={`${swatch.name} — ${swatch.hex}`}
              aria-label={`Copy ${swatch.name} ${swatch.hex}`}
              className={[
                "group relative aspect-square rounded-xl outline-none transition",
                "ring-1 ring-inset ring-black/5",
                "hover:scale-[1.06] active:scale-95",
                "focus-visible:ring-2 focus-visible:ring-slate-900 focus-visible:ring-offset-2",
                isCopied ? "scale-[1.06] ring-slate-900" : "",
              ].join(" ")}
              style={{ backgroundColor: swatch.hex }}
            >
              <span className="pointer-events-none absolute inset-0 grid place-items-center">
                <CopyIcon
                  className={[
                    "h-4 w-4 transition-opacity duration-150",
                    iconTone,
                    isCopied ? "opacity-0" : "opacity-0 group-hover:opacity-60",
                  ].join(" ")}
                />
              </span>

              <span className="pointer-events-none absolute inset-0 grid place-items-center">
                <CheckIcon
                  className={[
                    "h-5 w-5 transition-all duration-150",
                    iconTone,
                    isCopied ? "scale-100 opacity-100" : "scale-50 opacity-0",
                  ].join(" ")}
                />
              </span>
            </button>
          );
        })}
      </div>

      <div className="mt-4 min-h-[2.5rem]" aria-live="polite">
        {copied ? (
          <div className="flex items-center justify-center gap-2 rounded-xl bg-slate-50 px-3 py-2 text-sm ring-1 ring-slate-200">
            <span
              className="h-3.5 w-3.5 shrink-0 rounded-full ring-1 ring-inset ring-black/10"
              style={{ backgroundColor: copied.hex }}
            />
            <span className="font-mono font-medium text-slate-900">{copied.hex}</span>
            <span className="text-slate-500">copied</span>
          </div>
        ) : failed ? (
          <p className="rounded-xl bg-rose-50 px-3 py-2 text-center text-sm text-rose-700">
            Couldn&rsquo;t access the clipboard
          </p>
        ) : (
          <p className="py-2 text-center text-sm text-slate-400">
            Click a swatch to copy its hex code
          </p>
        )}
      </div>
    </div>
  );
}
```
### How the Swatch Grid Works

Each button shows the color, and the component handles all the feedback for you.

- **Copy-to-clipboard** – Clicking a swatch calls `copyText()`, which uses the modern Clipboard API with a `textarea` fallback for older browsers or non-secure contexts.
- **Visual feedback** – During hover, a small copy icon appears; once copied, the icon switches to a checkmark and the swatch briefly scales up. The bottom panel shows the copied hex code, a matching color dot, and the word "copied" for about 1.6 seconds.
- **Error handling** – If clipboard access fails, the status area displays a readable error message instead of the confirmation.
- **Accessibility** – Each button includes a descriptive `aria-label`, the status area uses `aria-live="polite"`, and focus-visible ring styles are included for keyboard users.
---

**Optimization Tip:** You can customize the palette by editing the `SWATCHES` array at the top of the file, and adjust the feedback duration via the `FEEDBACK_MS` constant.

