```tsx
import { useEffect, useRef, useState } from "react";

type Lap = {
  number: number;
  timeMs: number;
};

const formatTime = (ms: number) => {
  const totalCentiseconds = Math.floor(ms / 10);
  const centiseconds = totalCentiseconds % 100;
  const totalSeconds = Math.floor(totalCentiseconds / 100);
  const seconds = totalSeconds % 60;
  const minutes = Math.floor(totalSeconds / 60);

  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(
    2,
    "0"
  )}.${String(centiseconds).padStart(2, "0")}`;
};

export default function Stopwatch() {
  const [elapsedMs, setElapsedMs] = useState(0);
  const [isRunning, setIsRunning] = useState(false);
  const [laps, setLaps] = useState<Lap[]>([]);

  const elapsedRef = useRef(0);
  const startedAtRef = useRef<number | null>(null);

  const getCurrentElapsed = () => {
    const startedAt = startedAtRef.current;
    return startedAt === null ? elapsedRef.current : performance.now() - startedAt;
  };

  useEffect(() => {
    if (!isRunning) return;

    let frameId = 0;

    const tick = () => {
      const startedAt = startedAtRef.current;
      const nextElapsed =
        startedAt === null ? elapsedRef.current : performance.now() - startedAt;

      elapsedRef.current = nextElapsed;
      setElapsedMs(nextElapsed);
      frameId = requestAnimationFrame(tick);
    };

    frameId = requestAnimationFrame(tick);

    return () => cancelAnimationFrame(frameId);
  }, [isRunning]);

  const handleStartStop = () => {
    if (isRunning) {
      const finalElapsed = getCurrentElapsed();
      elapsedRef.current = finalElapsed;
      startedAtRef.current = null;
      setElapsedMs(finalElapsed);
      setIsRunning(false);
    } else {
      startedAtRef.current = performance.now() - elapsedRef.current;
      setIsRunning(true);
    }
  };

  const handleReset = () => {
    setIsRunning(false);
    startedAtRef.current = null;
    elapsedRef.current = 0;
    setElapsedMs(0);
    setLaps([]);
  };

  const handleLap = () => {
    if (!isRunning) return;

    const lapTime = getCurrentElapsed();

    setLaps((prev) => [
      ...prev,
      {
        number: prev.length + 1,
        timeMs: lapTime,
      },
    ]);
  };

  const lapsNewestFirst = [...laps].reverse();

  return (
    <div className="mx-auto w-full max-w-md rounded-2xl border border-slate-200 bg-white p-6 shadow-xl">
      <div className="rounded-xl bg-slate-950 px-6 py-8 text-center text-white shadow-inner">
        <div className="font-mono text-5xl font-semibold tabular-nums tracking-tight sm:text-6xl">
          {formatTime(elapsedMs)}
        </div>
      </div>

      <div className="mt-6 grid grid-cols-3 gap-3">
        <button
          type="button"
          onClick={handleStartStop}
          className={`rounded-xl px-4 py-3 text-sm font-semibold text-white shadow-sm transition ${
            isRunning
              ? "bg-rose-600 hover:bg-rose-700"
              : "bg-emerald-600 hover:bg-emerald-700"
          }`}
        >
          {isRunning ? "Stop" : "Start"}
        </button>

        <button
          type="button"
          onClick={handleLap}
          disabled={!isRunning}
          className="rounded-xl bg-slate-200 px-4 py-3 text-sm font-semibold text-slate-900 shadow-sm transition hover:bg-slate-300 disabled:cursor-not-allowed disabled:opacity-40"
        >
          Lap
        </button>

        <button
          type="button"
          onClick={handleReset}
          className="rounded-xl bg-slate-200 px-4 py-3 text-sm font-semibold text-slate-900 shadow-sm transition hover:bg-slate-300"
        >
          Reset
        </button>
      </div>

      <div className="mt-6">
        <h2 className="mb-2 text-sm font-semibold uppercase tracking-wide text-slate-500">
          Laps
        </h2>

        {lapsNewestFirst.length === 0 ? (
          <p className="rounded-xl border border-dashed border-slate-300 px-4 py-6 text-center text-sm text-slate-500">
            No laps recorded.
          </p>
        ) : (
          <ol className="max-h-64 space-y-2 overflow-y-auto pr-1">
            {lapsNewestFirst.map((lap) => (
              <li
                key={lap.number}
                className="flex items-center justify-between rounded-lg bg-slate-50 px-4 py-2 text-sm"
              >
                <span className="font-medium text-slate-700">
                  Lap {lap.number}
                </span>
                <span className="font-mono tabular-nums text-slate-900">
                  {formatTime(lap.timeMs)}
                </span>
              </li>
            ))}
          </ol>
        )}
      </div>
    </div>
  );
}
```

