```tsx
import { useEffect, useRef, useState } from "react";

function format(ms: number): string {
  const minutes = Math.floor(ms / 60000);
  const seconds = Math.floor((ms % 60000) / 1000);
  const centis = Math.floor((ms % 1000) / 10);
  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}.${String(centis).padStart(2, "0")}`;
}

export default function Stopwatch() {
  const [elapsed, setElapsed] = useState(0);
  const [running, setRunning] = useState(false);
  const [laps, setLaps] = useState<number[]>([]);
  const startedAt = useRef(0);

  useEffect(() => {
    if (!running) return;
    startedAt.current = performance.now() - elapsed;
    let frame = requestAnimationFrame(function tick() {
      setElapsed(performance.now() - startedAt.current);
      frame = requestAnimationFrame(tick);
    });
    return () => cancelAnimationFrame(frame);
    // elapsed is read once when the watch starts
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [running]);

  return (
    <div className="mx-auto mt-12 w-72 rounded-xl bg-zinc-900 p-6 text-zinc-100">
      <p className="text-center font-mono text-4xl tabular-nums">{format(elapsed)}</p>
      <div className="mt-4 grid grid-cols-3 gap-2">
        <button className="rounded bg-emerald-600 py-2" onClick={() => setRunning((r) => !r)}>
          {running ? "Stop" : "Start"}
        </button>
        <button className="rounded bg-zinc-700 py-2 disabled:opacity-40" disabled={!running}
          onClick={() => setLaps((prev) => [elapsed, ...prev])}>
          Lap
        </button>
        <button className="rounded bg-zinc-700 py-2" onClick={() => { setRunning(false); setElapsed(0); setLaps([]); }}>
          Reset
        </button>
      </div>
      <ol className="mt-4 space-y-1 font-mono text-sm">
        {laps.map((lap, i) => (
          <li key={laps.length - i} className="flex justify-between">
            <span>Lap {laps.length - i}</span>
            <span>{format(lap)}</span>
          </li>
        ))}
      </ol>
    </div>
  );
}
