```js
(function () {
  'use strict';

  const SYMBOLS = ['🍎', '🍌', '🍇', '🍓', '🍑', '🥝', '🍍', '🍉'];
  const TOTAL_PAIRS = SYMBOLS.length;

  const board = document.getElementById('board');
  const movesEl = document.getElementById('moves');
  const pairsEl = document.getElementById('pairs');
  const messageEl = document.getElementById('message');
  const shuffleBtn = document.getElementById('reshuffle');

  let firstCard = null;
  let secondCard = null;
  let lockBoard = false;
  let moves = 0;
  let matchedPairs = 0;
  let mismatchTimer = null;

  function shuffleArray(items) {
    const a = items.slice();
    for (let i = a.length - 1; i > 0; i -= 1) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }

  function createCard(symbol) {
    const card = document.createElement('button');
    card.type = 'button';
    card.className = 'card';
    card.dataset.symbol = symbol;
    card.setAttribute('aria-label', 'Face-down card');

    const inner = document.createElement('div');
    inner.className = 'card-inner';

    const back = document.createElement('div');
    back.className = 'card-face card-back';
    back.setAttribute('aria-hidden', 'true');

    const front = document.createElement('div');
    front.className = 'card-face card-front';
    front.setAttribute('aria-hidden', 'true');
    front.textContent = symbol;

    inner.append(back, front);
    card.append(inner);
    card.addEventListener('click', function () { flip(card); });
    return card;
  }

  function buildBoard() {
    const deck = shuffleArray(SYMBOLS.concat(SYMBOLS));
    const fragment = document.createDocumentFragment();
    deck.forEach(symbol => fragment.appendChild(createCard(symbol)));
    board.replaceChildren(fragment);
  }

  function flip(card) {
    if (lockBoard || card === firstCard || card.classList.contains('flipped')) return;

    card.classList.add('flipped');
    card.setAttribute('aria-label', 'Card showing ' + card.dataset.symbol);

    if (!firstCard) {
      firstCard = card;
      return;
    }

    secondCard = card;
    moves += 1;
    movesEl.textContent = String(moves);

    if (firstCard.dataset.symbol === secondCard.dataset.symbol) {
      matchPair();
    } else {
      mismatched();
    }
  }

  function matchPair() {
    const a = firstCard;
    const b = secondCard;
    firstCard = null;
    secondCard = null;

    a.classList.add('matched');
    b.classList.add('matched');
    a.disabled = true;
    b.disabled = true;
    a.setAttribute('aria-label', 'Matched pair');
    b.setAttribute('aria-label', 'Matched pair');

    matchedPairs += 1;
    pairsEl.textContent = matchedPairs + ' / ' + TOTAL_PAIRS;

    if (matchedPairs === TOTAL_PAIRS) {
      showWin();
    }
  }

  function mismatched() {
    lockBoard = true;
    const a = firstCard;
    const b = secondCard;

    mismatchTimer = window.setTimeout(function () {
      a.classList.remove('flipped');
      b.classList.remove('flipped');
      a.setAttribute('aria-label', 'Face-down card');
      b.setAttribute('aria-label', 'Face-down card');
      firstCard = null;
      secondCard = null;
      lockBoard = false;
      mismatchTimer = null;
    }, 800);
  }

  function showWin() {
    const label = moves === 1 ? 'move' : 'moves';
    messageEl.textContent = '🎉 All 8 pairs found in ' + moves + ' ' + label + '!';
    messageEl.classList.add('show');
  }

  function newGame() {
    if (mismatchTimer !== null) {
      window.clearTimeout(mismatchTimer);
      mismatchTimer = null;
    }
    firstCard = null;
    secondCard = null;
    lockBoard = false;
    moves = 0;
    matchedPairs = 0;
    movesEl.textContent = '0';
    pairsEl.textContent = '0 / ' + TOTAL_PAIRS;
    messageEl.classList.remove('show');
    messageEl.textContent = '';
    buildBoard();
  }

  shuffleBtn.addEventListener('click', newGame);

  newGame();
})();
